using System; using System.Web; using System.Web.Script.Serialization; using BabcoUnloadCompare.Web.Services;
namespace BabcoUnloadCompare.Web.Handlers { public class ExcelImport:IHttpHandler { public bool IsReusable=>false; public void ProcessRequest(HttpContext c){c.Response.ContentType="application/json";var js=new JavaScriptSerializer();try{var file=c.Request.Files["file"];UploadSecurity.Validate(file,UploadSecurity.ExcelExt);var po=c.Request.Form["poNumber"]??"";int receivingId=0;int.TryParse(c.Request.Form["receivingId"],out receivingId);var da=new DataAccess();var preview=new ExcelImportService().Preview(file.InputStream,file.FileName,da.GetPoItemMap(po));if(receivingId>0)da.LogImport(receivingId,UploadSecurity.SafeFileName(file.FileName),preview.MatchedRows.Count+preview.UnmatchedRows.Count,preview.MatchedRows.Count,preview.UnmatchedRows.Count,preview.Errors.Count==0?"Previewed":"Validation Error",string.Join("; ",preview.Errors));c.Response.Write(js.Serialize(new{IsSuccess=preview.Errors.Count==0,Message=preview.Errors.Count==0?"Import preview ready.":string.Join("; ",preview.Errors),Data=preview}));}catch(Exception ex){c.Response.StatusCode=400;c.Response.Write(js.Serialize(new{IsSuccess=false,Message=ex.Message}));}} } }
